L["Add return value"] = "Agregar valor de retorno"
-- en: "Lua returns multiple values in order. Each row documents one result."
L["Lua returns multiple values in order. Each row documents one result."] = "Lua devuelve varios valores en orden. Cada fila documenta un resultado."
